int walk_huge_page_range(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    unsigned long start = addr;
    unsigned long next = 0;
    int ret = 0;

    if (!walk || !walk->vma) {
        return -EINVAL;
    }

    if (addr >= end) {
        return 0;
    }

    while (start < end) {
        next = start + (1UL << walk->vma->vm_page_shift);
        if (next > end) {
            next = end;
        }

        if (walk->pmd_entry) {
            ret = walk->pmd_entry(start, next, walk);
            if (ret) {
                break;
            }
        }

        start = next;
    }

    return ret;
}
